(* [comment removed for export] *)
Lemma pmcs_norm : forall (b : bool) op n pix vd cvd v1 cv1 (L : list (Z * Z)),
     (b = true -> v1 = vd /\ cv1 = cvd) -> p_data v1 = p_data vd -> rsize v1 = rsize vd ->
     (p_cmap vd = 0 -> p_cmap v1 = 0) ->
     op <> pix -> op <> p_data vd -> (p_cmap vd <> 0 -> op <> c_arr cvd /\ op <> p_cmap vd) -> (p_cmap v1 <> 0 -> op <> c_arr cv1 /\ op <> p_cmap v1) ->
     (forall q k, In (q, k) L -> q <> op) ->
     (p_cmap vd <> 0 -> c_arr cvd <> p_cmap vd /\ pix <> c_arr cvd /\ pix <> p_cmap vd /\ p_data vd <> c_arr cvd /\ p_data vd <> p_cmap vd
                        /\ (forall q k, In (q, k) L -> q <> c_arr cvd /\ q <> p_cmap vd)) ->
     live_remove op (if b then (op, n) :: pm_copy_live pix vd cvd L else cmap_add_live (p_cmap v1) cv1 (cmap_rm_live (p_cmap vd) cvd ((op, n) :: pm_copy_live pix vd cvd L)))
     = pm_copy_live pix v1 cv1 L.
Proof.
