Lemma pmcs_final : forall sa arr p1 p2 (r1 r2 : list Z) pix v cv (L : list (Z * Z)),
  (forall q k, In (q, k) ((if p_cmap v =? 0 then [] else [(c_arr cv, 4 * c_nalloc cv); (p_cmap v, 24)]) ++ [(p_data v, rsize v); (pix, 64)]) ->
     q <> sa /\ q <> arr /\ q <> p1 /\ q <> p2) ->
  (forall q k, In (q, k) L -> q <> sa /\ q <> arr /\ q <> p1 /\ q <> p2) ->
  List.NoDup [sa; arr; p1; p2] ->
  sarray_destroy_live sa (mkSav 2 arr [(p1, r1); (p2, r2)]) (pm_copy_live pix v cv ((p2, 7) :: (p1, 6) :: (arr, 400) :: (sa, 24) :: L))
  = pm_copy_live pix v cv L.
